import{_ as e,c as o,o as a,ag as r}from"./chunks/framework.BwVZiZlf.js";const u=JSON.parse('{"title":"How to Protect Your Teeth?","description":"","frontmatter":{"date":"2025-04-05T00:00:00.000Z","recommend":false},"headers":[],"relativePath":"blog/2025/04/05/how-to-protect-our-teeth.md","filePath":"blog/2025/04/05/how-to-protect-our-teeth.md","lastUpdated":1786674252000}'),n={name:"blog/2025/04/05/how-to-protect-our-teeth.md"};function h(s,t,i,l,d,p){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1743811200000"},t[0]||(t[0]=[r('<h1 id="how-to-protect-your-teeth" tabindex="-1">How to Protect Your Teeth? <a class="header-anchor" href="#how-to-protect-your-teeth" aria-label="Permalink to &quot;How to Protect Your Teeth?&quot;">​</a></h1><p>This afternoon, I visited the dentist for periodontal treatment.</p><p>After comparing CT scans of healthy teeth and mine, the dentist told me that my periodontitis is quite severe. If I don’t take action, I could lose many teeth.</p><p>Following the doctor’s advice, I underwent periodontal scaling. Although I was given anesthesia, I still felt a bit of soreness. The treatment cost me a total of 1,666 yuan.</p><p>At the end of the appointment, the nurse explained the post-treatment precautions and taught me how to use dental floss properly.</p><p>When I was leaving the hospital, I asked the front desk staff whether Suzhou Stomatological Hospital is the best dental hospital in Suzhou. She smiled and said she didn’t know.</p><p>After returning home, I took a rest and then watched a BBC documentary with my son.</p><p>The best part of today was teaching my son how to calculate 1 + 2 + 3 + … + 10,000, even though he’s just a first grader in elementary school!</p><h2 id="how-to-protect-our-teeth" tabindex="-1">How to Protect Our Teeth <a class="header-anchor" href="#how-to-protect-our-teeth" aria-label="Permalink to &quot;How to Protect Our Teeth&quot;">​</a></h2><p>In the early stages of dental inflammation, there are usually no symptoms. If you wait until your teeth start hurting, you’re already late to the party. The damage is probably done by then. Therefore, the first and most important point is to visit the dentist regularly for check-ups.</p><p>In daily life, we should make it a habit to brush our teeth after meals, floss correctly, remove food debris between teeth promptly, and have a professional dental cleaning at least once a year.</p><p>That’s all for today!</p>',12)]))}const m=e(n,[["render",h]]);export{u as __pageData,m as default};
